"use client";

import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardBody,
  CardFooter,
  Button,
} from "@heroui/react";

import {
  CalendarDays,
  MapPin,
  Clock,
  Ticket,
  Check,
  Download,
  Share2,
} from "lucide-react";

interface Show {
  id: number;
  date: Date;
  venue: string;
  time: string;
  available: boolean;
}

interface BookingDetails {
  name: string;
  email: string;
  phone: string;
  tickets: string;
  specialRequests: string;
}

interface BookingConfirmationProps {
  show: Show;
  bookingDetails: BookingDetails;
  onBackToHome: () => void;
}

export default function BookingConfirmation({
  show,
  bookingDetails,
  onBackToHome,
}: BookingConfirmationProps) {
  const ticketLabel = `${parseInt(bookingDetails.tickets)} ${
    parseInt(bookingDetails.tickets) === 1 ? "ticket" : "tickets"
  }`;

  return (
    <Card className="mt-8 w-full max-w-4xl mx-auto">
      <CardHeader className="text-center border-b pb-6">
        <div className="mx-auto bg-primary/10 rounded-full p-3 w-fit mb-4">
          <Check className="h-8 w-8 text-primary" />
        </div>
        <h3 className="text-2xl font-bold">Booking Confirmed!</h3>
        <p>Your tickets have been reserved</p>
      </CardHeader>

      <CardBody className="pt-6">
        <div className="grid gap-8 md:grid-cols-2">
          {/* Show Details */}
          <div>
            <h3 className="text-lg font-semibold mb-4">Show Details</h3>
            <div className="space-y-4 text-sm">
              <DetailItem icon={<CalendarDays />} label="Date">
                {show.date.toLocaleDateString("en-US", {
                  weekday: "long",
                  month: "long",
                  day: "numeric",
                  year: "numeric",
                })}
              </DetailItem>
              <DetailItem icon={<Clock />} label="Time">
                {show.time}
              </DetailItem>
              <DetailItem icon={<MapPin />} label="Venue">
                {show.venue}
              </DetailItem>
              <DetailItem icon={<Ticket />} label="Tickets">
                {ticketLabel}
              </DetailItem>
            </div>
          </div>

          {/* Booking Details */}
          <div>
            <h3 className="text-lg font-semibold mb-4">Booking Information</h3>
            <div className="space-y-4 text-sm">
              <InfoItem label="Name">{bookingDetails.name}</InfoItem>
              <InfoItem label="Email">{bookingDetails.email}</InfoItem>
              <InfoItem label="Phone">{bookingDetails.phone}</InfoItem>
              {bookingDetails.specialRequests && (
                <InfoItem label="Special Requests">
                  {bookingDetails.specialRequests}
                </InfoItem>
              )}
            </div>
          </div>
        </div>

        <div className="mt-8 p-4 bg-muted rounded-lg text-sm text-muted-foreground">
          <p>
            <strong className="text-foreground">Important:</strong> A confirmation email has been sent to{" "}
            <span className="font-medium">{bookingDetails.email}</span>. Please arrive 15 minutes before the show. For
            questions or changes, contact us at{" "}
            <a href="mailto:support@comedyshows.com" className="underline">
              support@comedyshows.com
            </a>{" "}
            or call (555) 123-4567.
          </p>
        </div>
      </CardBody>

      <CardFooter className="flex flex-col sm:flex-row gap-4 pt-6">
        <Button variant="bordered" onClick={onBackToHome} className="w-full sm:w-auto">
          Back to Home
        </Button>
        <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto sm:ml-auto">
          <Button variant="bordered" className="flex-1">
            <Download className="mr-2 h-4 w-4" />
            Download Ticket
          </Button>
          <Button className="flex-1">
            <Share2 className="mr-2 h-4 w-4" />
            Share
          </Button>
        </div>
      </CardFooter>
    </Card>
  );
}

// Reusable UI detail item with icon
function DetailItem({ icon, label, children }: { icon: React.ReactNode; label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start gap-3">
      <div className="mt-1 text-muted-foreground">{icon}</div>
      <div>
        <p className="font-semibold">{label}</p>
        <p className="text-muted-foreground">{children}</p>
      </div>
    </div>
  );
}

// Reusable label/info block
function InfoItem({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="font-semibold">{label}</p>
      <p className="text-muted-foreground">{children}</p>
    </div>
  );
}
