"use client";

import { useMemo } from "react";
import {
  Card,
  CardHeader,
 
  CardBody,
  CardFooter,
  Button,
} from "@heroui/react";
import {
  CalendarDays,
  MapPin,
  Clock,
  Ticket,
  Check,
  Download,
  Share2,
} from "lucide-react";

interface Show {
  id: number;
  date: Date;
  venue: string;
  time: string;
  available: boolean;
}

interface BookingDetails {
  name: string;
  email: string;
  phone: string;
  tickets: string;
  specialRequests: string;
}

interface BookingConfirmationProps {
  show: Show;
  bookingDetails: BookingDetails;
  onBackToHome: () => void;
}

export default function BookingConfirmation({
  show,
  bookingDetails,
  onBackToHome,
}: BookingConfirmationProps) {
  const ticketLabel = useMemo(() => {
    const count = parseInt(bookingDetails.tickets, 10);
    return `${count} ${count === 1 ? "ticket" : "tickets"}`;
  }, [bookingDetails.tickets]);

  return (
    <Card className="mt-8">
      <CardHeader className="text-center border-b pb-6">
        <div className="mx-auto bg-primary/10 rounded-full p-3 w-fit mb-4">
          <Check className="h-8 w-8 text-primary" />
        </div>

      </CardHeader>

      <CardBody className="pt-6">
        <div className="grid gap-6 md:grid-cols-2">
          {/* Show Details */}
          <div>
            <h3 className="text-lg font-medium mb-4">Show Details</h3>
            <div className="space-y-4 text-sm">
              <div className="flex items-start gap-3">
                <CalendarDays className="h-5 w-5 text-muted-foreground mt-1" />
                <div>
                  <p className="font-semibold">Date</p>
                  <p className="text-muted-foreground">
                    {show.date.toLocaleDateString("en-US", {
                      weekday: "long",
                      month: "long",
                      day: "numeric",
                      year: "numeric",
                    })}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Clock className="h-5 w-5 text-muted-foreground mt-1" />
                <div>
                  <p className="font-semibold">Time</p>
                  <p className="text-muted-foreground">{show.time}</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <MapPin className="h-5 w-5 text-muted-foreground mt-1" />
                <div>
                  <p className="font-semibold">Venue</p>
                  <p className="text-muted-foreground">{show.venue}</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Ticket className="h-5 w-5 text-muted-foreground mt-1" />
                <div>
                  <p className="font-semibold">Tickets</p>
                  <p className="text-muted-foreground">{ticketLabel}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Booking Details */}
          <div>
            <h3 className="text-lg font-medium mb-4">Booking Information</h3>
            <div className="space-y-4 text-sm">
              <div>
                <p className="font-semibold">Name</p>
                <p className="text-muted-foreground">{bookingDetails.name}</p>
              </div>
              <div>
                <p className="font-semibold">Email</p>
                <p className="text-muted-foreground">{bookingDetails.email}</p>
              </div>
              <div>
                <p className="font-semibold">Phone</p>
                <p className="text-muted-foreground">{bookingDetails.phone}</p>
              </div>
              {bookingDetails.specialRequests && (
                <div>
                  <p className="font-semibold">Special Requests</p>
                  <p className="text-muted-foreground">
                    {bookingDetails.specialRequests}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="mt-8 p-4 bg-muted rounded-lg text-sm">
          <p>
            <span className="font-semibold">Important:</span> A confirmation
            email has been sent to{" "}
            <span className="font-medium">{bookingDetails.email}</span> with
            your ticket details. Please arrive 15 minutes before the show
            starts. For questions or changes, contact us at{" "}
            <a href="mailto:support@comedyshows.com" className="underline">
              support@comedyshows.com
            </a>{" "}
            or call <span className="font-medium">(555) 123-4567</span>.
          </p>
        </div>
      </CardBody>

      <CardFooter className="flex flex-col sm:flex-row gap-4 pt-6">
        <Button
          className="w-full sm:w-auto"
          variant="bordered"
          onClick={onBackToHome}
        >
          Back to Home
        </Button>
        <div className="flex gap-4 w-full sm:w-auto sm:ml-auto">
          <Button className="flex-1" variant="bordered">
            <Download className="mr-2 h-4 w-4" />
            Download Tickets
          </Button>
          <Button className="flex-1">
            <Share2 className="mr-2 h-4 w-4" />
            Share
          </Button>
        </div>
      </CardFooter>
    </Card>
  );
}
